using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;

    ll left = max({
        1LL,
        1 - b + c,
        1 - a + d,
        1 - a - b + c + d
    });

    ll right = min({
        n,
        n - b + c,
        n - a + d,
        n - a - b + c + d
    });

    ll valid = max(0LL, right - left + 1);
    cout << valid * n << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;

    ll offsets[] = {0, b - c, a - d, a + b - c - d};
    ll low = 1, high = n;

    for (ll offset : offsets) {
        low = max(low, 1 - offset);
        high = min(high, n - offset);
    }

    ll valid = max(0LL, high - low + 1);
    cout << valid * n << '\n';

    return 0;
}

